queries.sphinxql:
	create table t523 ( test text );
 	insert into t523 (id, test) values (1, '<html><body><p>What will happen to ecosia.</p><p>Ecosia test</p></body></html>');
	CALL SNIPPETS ('<a>x.<i>x</i></a>', 't523', 'x', 0 AS limit, 'retain' AS html_strip_mode);
	CALL SNIPPETS ('<html><body><p>What will happen to ecosia.</p><p>Ecosia test</p></body></html>', 't523', 'ecosia', 1 AS use_boundaries, 1 AS query_mode, 0 AS around, 0 AS limit, 'retain' AS html_strip_mode, '<span class="snippet">' AS before_match, '</span>' AS after_match);
	CALL SNIPPETS ('<a>x.<i></i><u>x</u> y x</a>', 't523', 'x', 0 AS limit, 'retain' AS html_strip_mode, '<b id="%PASSAGE_ID%">' AS before_match, '</b><!--%PASSAGE_ID%-->' AS after_match, 100 AS start_passage_id);
	SELECT id, HIGHLIGHT({html_strip_mode=retain,use_boundaries=1,query_mode=1,around=0,limit=0,before_match='<span class="snippet">',after_match='</span>'},test) AS highlight FROM t523 WHERE MATCH('Ecosia');
	drop table t523;
